package com.plugheatmap;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import lombok.Getter;
import lombok.Value;

/**
 * Grid of heat values covering an area of the canvas, plus a rendered image of it.
 * Only accessed from the client thread.
 */
class Heatmap
{
	// heat below this fraction of the scale fades in rather than popping in at full opacity
	private static final float FADE_IN = 0.2f;

	@Getter
	private int x;
	@Getter
	private int y;
	@Getter
	private int width;
	@Getter
	private int height;
	private int cellSize;
	private int cols;
	private int rows;
	private float[] heat = new float[0];
	private float maxHeat;
	private boolean dirty;

	private final int[] palette = new int[256];
	private BufferedImage cells;
	private BufferedImage image;

	/**
	 * Fits the grid to an area of the canvas. Heat is kept relative to the area's corner, so moving or resizing
	 * the area keeps the overlapping cells. A new cell size clears the heatmap.
	 */
	void resize(int x, int y, int width, int height, int cellSize)
	{
		if (x == this.x && y == this.y && width == this.width && height == this.height && cellSize == this.cellSize)
		{
			return;
		}

		int newCols = (width + cellSize - 1) / cellSize;
		int newRows = (height + cellSize - 1) / cellSize;
		float[] newHeat = new float[newCols * newRows];

		if (cellSize == this.cellSize)
		{
			for (int row = 0; row < Math.min(rows, newRows); row++)
			{
				System.arraycopy(heat, row * cols, newHeat, row * newCols, Math.min(cols, newCols));
			}
		}

		this.x = x;
		this.y = y;
		this.width = width;
		this.height = height;
		this.cellSize = cellSize;
		cols = newCols;
		rows = newRows;
		heat = newHeat;
		maxHeat = 0;
		for (float h : heat)
		{
			maxHeat = Math.max(maxHeat, h);
		}

		cells = width > 0 && height > 0 ? new BufferedImage(cols, rows, BufferedImage.TYPE_INT_ARGB) : null;
		image = width > 0 && height > 0 ? new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB) : null;
		dirty = true;
	}

	/**
	 * Adds heat around a point relative to the mapped area, falling off linearly with distance.
	 */
	void add(int x, int y, int radius)
	{
		int cx = x / cellSize;
		int cy = y / cellSize;
		int reach = (radius + cellSize - 1) / cellSize;
		float falloff = radius + cellSize;

		for (int row = Math.max(0, cy - reach); row <= Math.min(rows - 1, cy + reach); row++)
		{
			for (int col = Math.max(0, cx - reach); col <= Math.min(cols - 1, cx + reach); col++)
			{
				float dx = (col + 0.5f) * cellSize - x;
				float dy = (row + 0.5f) * cellSize - y;
				float weight = 1 - (float) Math.sqrt(dx * dx + dy * dy) / falloff;
				if (weight > 0)
				{
					int i = row * cols + col;
					heat[i] += weight;
					maxHeat = Math.max(maxHeat, heat[i]);
				}
			}
		}
		dirty = true;
	}

	void decay(float factor)
	{
		if (maxHeat == 0)
		{
			return;
		}

		for (int i = 0; i < heat.length; i++)
		{
			heat[i] *= factor;
		}
		maxHeat *= factor;
		dirty = true;
	}

	/**
	 * Copies the heat grid, for saving.
	 */
	Snapshot snapshot()
	{
		return new Snapshot(cellSize, cols, rows, heat.clone());
	}

	/**
	 * Replaces the heat grid with a saved one. It's fitted to the mapped area on the next {@link #resize}, which
	 * discards it if the cell size has changed since it was saved.
	 */
	void restore(Snapshot snapshot)
	{
		cellSize = snapshot.getCellSize();
		cols = snapshot.getCols();
		rows = snapshot.getRows();
		heat = snapshot.getHeat();
		// force the next resize to refit the grid, and draw nothing until then
		width = -1;
		height = -1;
		cells = null;
		image = null;
	}

	void clear()
	{
		heat = new float[cols * rows];
		maxHeat = 0;
		dirty = true;
	}

	/**
	 * Rebuilds the colour ramp: cold to warm over the lower half of the scale, warm to hot over the upper half.
	 */
	void setColors(Color cold, Color warm, Color hot, int opacityPercent)
	{
		float maxAlpha = opacityPercent * 255 / 100f;
		for (int i = 0; i < palette.length; i++)
		{
			float t = i / (float) (palette.length - 1);
			Color c = t < 0.5f ? lerp(cold, warm, t * 2) : lerp(warm, hot, (t - 0.5f) * 2);
			int alpha = Math.round(maxAlpha * Math.min(1, t / FADE_IN));
			palette[i] = alpha << 24 | (c.getRGB() & 0xFFFFFF);
		}
		dirty = true;
	}

	/**
	 * Redraws the image of the mapped area if the heat or colours changed since the last call.
	 *
	 * @param minScale the heat shown as fully hot while nothing is hotter, so the map warms up gradually
	 */
	void render(float minScale, boolean smooth)
	{
		if (!dirty || image == null)
		{
			return;
		}
		dirty = false;

		int[] pixels = ((DataBufferInt) cells.getRaster().getDataBuffer()).getData();
		// log scale so one spot the mouse rested on doesn't wash out everything else
		double logMax = Math.log1p(Math.max(maxHeat, minScale));
		for (int i = 0; i < heat.length; i++)
		{
			if (heat[i] <= 0)
			{
				pixels[i] = 0;
				continue;
			}
			int index = (int) (Math.log1p(heat[i]) / logMax * (palette.length - 1));
			pixels[i] = palette[Math.min(index, palette.length - 1)];
		}

		Graphics2D g = image.createGraphics();
		g.setComposite(AlphaComposite.Src);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, smooth
			? RenderingHints.VALUE_INTERPOLATION_BILINEAR
			: RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(cells, 0, 0, cols * cellSize, rows * cellSize, null);
		g.dispose();
	}

	BufferedImage getImage()
	{
		return image;
	}

	private static Color lerp(Color a, Color b, float t)
	{
		return new Color(
			Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	@Value
	static class Snapshot
	{
		int cellSize;
		int cols;
		int rows;
		float[] heat;
	}
}

package com.plugheatmap;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(HeatmapConfig.GROUP)
public interface HeatmapConfig extends Config
{
	String GROUP = "mouseheatmap";
	String SHOW_HEATMAP = "showHeatmap";
	String INCLUDE_INTERFACES = "includeInterfaces";
	String REMEMBER_HEATMAP = "rememberHeatmap";

	@ConfigSection(
		name = "Advanced",
		description = "Grid, timing and rendering tweaks",
		position = 10,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = SHOW_HEATMAP,
		name = "Show heatmap",
		description = "Draw the heatmap over the game view. Mouse movement is still recorded while hidden",
		position = 0
	)
	default boolean showHeatmap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "toggleKeybind",
		name = "Toggle hotkey",
		description = "Hotkey to show or hide the heatmap",
		position = 1
	)
	default Keybind toggleKeybind()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = INCLUDE_INTERFACES,
		name = "Include interfaces",
		description = "Map the whole client, including the inventory, chat and other interfaces, and draw over them."
			+ " Each side panel tab can have its own heatmap",
		position = 2
	)
	default boolean includeInterfaces()
	{
		return true;
	}

	@ConfigItem(
		keyName = "splitTabs",
		name = "Separate tab heatmaps",
		description = "Keep a separate heatmap for each side panel tab, such as inventory, prayer and spellbook."
			+ " Needs Include interfaces",
		position = 3
	)
	default boolean splitTabs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "coldColor",
		name = "Cold colour",
		description = "Colour of the least visited areas",
		position = 4
	)
	default Color coldColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "warmColor",
		name = "Warm colour",
		description = "Colour of moderately visited areas",
		position = 5
	)
	default Color warmColor()
	{
		return Color.YELLOW;
	}

	@ConfigItem(
		keyName = "hotColor",
		name = "Hot colour",
		description = "Colour of the most visited areas",
		position = 6
	)
	default Color hotColor()
	{
		return Color.RED;
	}

	@Range(max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "opacity",
		name = "Opacity",
		description = "Opacity of the hottest areas",
		position = 7
	)
	default int opacity()
	{
		return 50;
	}

	@ConfigItem(
		keyName = REMEMBER_HEATMAP,
		name = "Remember heatmap",
		description = "Save the heatmap and restore it next time the client starts",
		position = 8
	)
	default boolean rememberHeatmap()
	{
		return true;
	}

	@Range(min = 2, max = 50)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "cellSize",
		name = "Cell size",
		description = "Size of each heatmap cell. Changing this clears the heatmap",
		position = 0,
		section = advancedSection
	)
	default int cellSize()
	{
		return 5;
	}

	@Range(max = 100)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "radius",
		name = "Spread radius",
		description = "How far around the pointer heat is added",
		position = 1,
		section = advancedSection
	)
	default int radius()
	{
		return 5;
	}

	@Range(min = 20, max = 1000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "sampleInterval",
		name = "Sample interval",
		description = "How often the mouse position is recorded",
		position = 2,
		section = advancedSection
	)
	default int sampleInterval()
	{
		return 20;
	}

	@Range(min = 20, max = 5000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "renderInterval",
		name = "Update interval",
		description = "How often the drawn heatmap is refreshed",
		position = 3,
		section = advancedSection
	)
	default int renderInterval()
	{
		return 200;
	}

	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "fadeMinutes",
		name = "Fade half-life",
		description = "Time for heat to fade to half. 0 never fades",
		position = 4,
		section = advancedSection
	)
	default int fadeMinutes()
	{
		return 0;
	}

	@Range(max = 3600)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "timeToHot",
		name = "Time to hot",
		description = "How long the mouse must spend over a spot before it shows the hot colour. Until a spot gets"
			+ " there, the map builds up gradually; after that, colours are relative to the hottest spot."
			+ " 0 always shows the hottest spot as hot",
		position = 5,
		section = advancedSection
	)
	default int timeToHot()
	{
		return 90;
	}

	@ConfigItem(
		keyName = "ignoreIdle",
		name = "Ignore idle mouse",
		description = "Only record while the mouse is moving or clicking, so a resting pointer doesn't build up heat",
		position = 6,
		section = advancedSection
	)
	default boolean ignoreIdle()
	{
		return true;
	}

	@ConfigItem(
		keyName = "smooth",
		name = "Smooth",
		description = "Blend cells together instead of drawing hard-edged squares",
		position = 7,
		section = advancedSection
	)
	default boolean smooth()
	{
		return true;
	}

	@ConfigItem(
		keyName = "resetKeybind",
		name = "Reset hotkey",
		description = "Hotkey to clear the heatmap",
		position = 8,
		section = advancedSection
	)
	default Keybind resetKeybind()
	{
		return Keybind.NOT_SET;
	}
}

package com.plugheatmap;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class HeatmapOverlay extends Overlay
{
	private final HeatmapConfig config;
	private final HeatmapPlugin plugin;

	@Inject
	HeatmapOverlay(HeatmapConfig config, HeatmapPlugin plugin)
	{
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		updateLayer();
	}

	/**
	 * Draws over interfaces when mapping them, otherwise above the 3D scene but below interfaces so they cover it.
	 * The overlay must be re-added to the overlay manager for a change to take effect.
	 */
	void updateLayer()
	{
		setLayer(config.includeInterfaces() ? OverlayLayer.ABOVE_WIDGETS : OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showHeatmap())
		{
			return null;
		}

		Heatmap heatmap = plugin.getHeatmap();
		Heatmap tabHeatmap = plugin.getTabHeatmap();
		if (tabHeatmap == null)
		{
			draw(graphics, heatmap);
			return null;
		}

		// leave the side panel to the open tab's heatmap
		Rectangle panel = new Rectangle(tabHeatmap.getX(), tabHeatmap.getY(), tabHeatmap.getWidth(), tabHeatmap.getHeight());
		Area outsidePanel = new Area(new Rectangle(heatmap.getX(), heatmap.getY(), heatmap.getWidth(), heatmap.getHeight()));
		outsidePanel.subtract(new Area(panel));

		Shape clip = graphics.getClip();
		graphics.clip(outsidePanel);
		draw(graphics, heatmap);
		graphics.setClip(clip);
		draw(graphics, tabHeatmap);
		return null;
	}

	private static void draw(Graphics2D graphics, Heatmap heatmap)
	{
		BufferedImage image = heatmap.getImage();
		if (image != null)
		{
			graphics.drawImage(image, heatmap.getX(), heatmap.getY(), null);
		}
	}
}

package com.plugheatmap;

import com.google.inject.Provides;
import com.plugheatmap.HeatmapStorage.Saved;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Point;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.HotkeyListener;

@Slf4j
@PluginDescriptor(
	name = "Mouse Heatmap",
	internalName = "mouse-heatmap",
	description = "Draws a heatmap of where your mouse spends its time over the game view",
	tags = {"mouse", "heatmap", "overlay"}
)
public class HeatmapPlugin extends Plugin
{
	// the side panel tab content area for fixed, resizable classic and resizable modern layouts
	private static final int[] SIDE_PANELS = {
		InterfaceID.Toplevel.SIDE_PANELS,
		InterfaceID.ToplevelOsrsStretch.SIDE_PANELS,
		InterfaceID.ToplevelPreEoc.SIDE_PANELS,
	};

	// a click counts the mouse as active for one game tick, even if it hasn't moved
	private static final long CLICK_ACTIVE_MILLIS = 600;
	private static final long SAVE_INTERVAL_MILLIS = 60_000;
	private static final String SAVE_FILE = "heatmap.dat";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private HeatmapConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private HeatmapOverlay overlay;

	@Inject
	private ScheduledExecutorService executor;

	@Getter
	private final Heatmap heatmap = new Heatmap();

	// keyed by open side panel tab
	private final Map<Integer, Heatmap> tabHeatmaps = new HashMap<>();

	/**
	 * The heatmap for the open side panel tab, or null when tabs aren't split or no panel is open.
	 */
	@Getter
	private Heatmap tabHeatmap;

	private long lastSampleMillis;
	private long lastRenderMillis;
	private long lastSaveMillis;
	// false until any saved heatmap has been loaded, so an empty one can't overwrite it
	private volatile boolean loaded;
	private Point lastMouse;
	// written on the AWT thread, read on the client thread
	private volatile long lastClickMillis;

	private final HotkeyListener toggleListener = new HotkeyListener(() -> config.toggleKeybind())
	{
		@Override
		public void hotkeyPressed()
		{
			configManager.setConfiguration(HeatmapConfig.GROUP, HeatmapConfig.SHOW_HEATMAP, !config.showHeatmap());
		}
	};

	private final HotkeyListener resetListener = new HotkeyListener(() -> config.resetKeybind())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(HeatmapPlugin.this::clear);
		}
	};

	private final MouseAdapter clickListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			lastClickMillis = System.currentTimeMillis();
			return event;
		}
	};

	@Override
	protected void startUp() throws Exception
	{
		clientThread.invoke(this::updateColors);
		overlayManager.add(overlay);
		keyManager.registerKeyListener(toggleListener);
		keyManager.registerKeyListener(resetListener);
		mouseManager.registerMouseListener(clickListener);

		loaded = false;
		if (config.rememberHeatmap())
		{
			executor.execute(this::load);
		}
		else
		{
			loaded = true;
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		keyManager.unregisterKeyListener(toggleListener);
		keyManager.unregisterKeyListener(resetListener);
		mouseManager.unregisterMouseListener(clickListener);
		clientThread.invoke(() ->
		{
			if (config.rememberHeatmap() && loaded)
			{
				Saved saved = snapshot();
				executor.execute(() -> write(saved));
			}
			clear();
		});
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (!config.rememberHeatmap() || !loaded)
		{
			return;
		}

		CompletableFuture<Saved> saved = new CompletableFuture<>();
		clientThread.invoke(() -> saved.complete(snapshot()));
		event.waitFor(saved.thenAcceptAsync(this::write, executor));
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (config.includeInterfaces())
		{
			heatmap.resize(0, 0, client.getCanvasWidth(), client.getCanvasHeight(), config.cellSize());
		}
		else
		{
			heatmap.resize(client.getViewportXOffset(), client.getViewportYOffset(),
				client.getViewportWidth(), client.getViewportHeight(), config.cellSize());
		}
		updateTabHeatmap();

		long now = System.currentTimeMillis();
		if (now - lastSampleMillis >= config.sampleInterval())
		{
			lastSampleMillis = now;
			sample(now);
		}

		long sinceRender = now - lastRenderMillis;
		if (sinceRender >= config.renderInterval())
		{
			lastRenderMillis = now;
			// cap the elapsed time so the first render after logging in doesn't fade everything away
			sinceRender = Math.min(sinceRender, config.renderInterval());
			float decay = config.fadeMinutes() > 0
				? (float) Math.pow(0.5, sinceRender / (config.fadeMinutes() * 60_000.0))
				: 1;
			render(heatmap, decay);
			for (Heatmap tab : tabHeatmaps.values())
			{
				render(tab, decay);
			}
		}

		if (config.rememberHeatmap() && loaded && now - lastSaveMillis >= SAVE_INTERVAL_MILLIS)
		{
			lastSaveMillis = now;
			Saved saved = snapshot();
			executor.execute(() -> write(saved));
		}
	}

	private void render(Heatmap map, float decay)
	{
		if (decay < 1)
		{
			map.decay(decay);
		}
		// a pointer resting on a cell adds about 1 heat per sample
		float minScale = config.timeToHot() * 1000f / config.sampleInterval();
		map.render(minScale, config.smooth());
	}

	private void updateTabHeatmap()
	{
		Rectangle panel = config.includeInterfaces() && config.splitTabs() ? findSidePanel() : null;
		if (panel == null)
		{
			tabHeatmap = null;
			return;
		}

		int tab = client.getVarcIntValue(VarClientID.TOPLEVEL_PANEL);
		tabHeatmap = tabHeatmaps.computeIfAbsent(tab, t -> newHeatmap());
		tabHeatmap.resize(panel.x, panel.y, panel.width, panel.height, config.cellSize());
	}

	private Heatmap newHeatmap()
	{
		Heatmap map = new Heatmap();
		setColors(map);
		return map;
	}

	private Rectangle findSidePanel()
	{
		for (int id : SIDE_PANELS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				return widget.getBounds();
			}
		}
		return null;
	}

	private void sample(long now)
	{
		Point mouse = client.getMouseCanvasPosition();
		boolean idle = mouse.equals(lastMouse) && now - lastClickMillis > CLICK_ACTIVE_MILLIS;
		lastMouse = mouse;
		if (client.isMenuOpen() || (idle && config.ignoreIdle()))
		{
			return;
		}

		if (tabHeatmap == null || !add(tabHeatmap, mouse))
		{
			add(heatmap, mouse);
		}
	}

	/**
	 * Adds heat at a canvas point if it's inside the heatmap's area.
	 */
	private boolean add(Heatmap map, Point mouse)
	{
		int x = mouse.getX() - map.getX();
		int y = mouse.getY() - map.getY();
		if (x < 0 || y < 0 || x >= map.getWidth() || y >= map.getHeight())
		{
			return false;
		}
		map.add(x, y, config.radius());
		return true;
	}

	/**
	 * Copies every heatmap for saving. Must run on the client thread.
	 */
	private Saved snapshot()
	{
		Map<Integer, Heatmap.Snapshot> tabs = new HashMap<>();
		tabHeatmaps.forEach((tab, map) -> tabs.put(tab, map.snapshot()));
		return new Saved(heatmap.snapshot(), tabs);
	}

	private void restore(Saved saved)
	{
		heatmap.restore(saved.getHeatmap());
		tabHeatmaps.clear();
		saved.getTabHeatmaps().forEach((tab, snapshot) ->
		{
			Heatmap map = newHeatmap();
			map.restore(snapshot);
			tabHeatmaps.put(tab, map);
		});
		tabHeatmap = null;
	}

	private Filepath saveFile() throws IOException
	{
		return getPluginDirectory().joinSegment(SAVE_FILE);
	}

	private void load()
	{
		try
		{
			Filepath file = saveFile();
			if (file.exists())
			{
				Saved saved = HeatmapStorage.read(file);
				clientThread.invoke(() ->
				{
					restore(saved);
					loaded = true;
				});
				return;
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to load saved heatmap", e);
		}
		loaded = true;
	}

	private void write(Saved saved)
	{
		try
		{
			HeatmapStorage.write(saveFile(), saved);
		}
		catch (IOException e)
		{
			log.warn("Failed to save heatmap", e);
		}
	}

	private void clear()
	{
		heatmap.clear();
		tabHeatmaps.clear();
		tabHeatmap = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!HeatmapConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (HeatmapConfig.REMEMBER_HEATMAP.equals(event.getKey()) && config.rememberHeatmap())
		{
			// keep the current session's heatmap and save it from now on
			loaded = true;
		}

		if (HeatmapConfig.INCLUDE_INTERFACES.equals(event.getKey()))
		{
			overlayManager.remove(overlay);
			overlay.updateLayer();
			overlayManager.add(overlay);
		}

		// also marks the heatmaps dirty, so scale and smoothing changes redraw too
		clientThread.invoke(this::updateColors);
	}

	private void updateColors()
	{
		setColors(heatmap);
		tabHeatmaps.values().forEach(this::setColors);
	}

	private void setColors(Heatmap map)
	{
		map.setColors(config.coldColor(), config.warmColor(), config.hotColor(), config.opacity());
	}

	@Provides
	HeatmapConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HeatmapConfig.class);
	}
}

package com.plugheatmap;

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import lombok.Value;
import net.runelite.client.util.Filepath;

/**
 * Reads and writes saved heatmaps as a gzipped binary file. Does blocking IO, so keep it off the client thread.
 */
class HeatmapStorage
{
	private static final int MAGIC = 0x4D484D50; // "MHMP"
	private static final int VERSION = 1;
	// guards against allocating huge arrays from a corrupt file
	private static final int MAX_CELLS = 10_000_000;

	@Value
	static class Saved
	{
		Heatmap.Snapshot heatmap;
		Map<Integer, Heatmap.Snapshot> tabHeatmaps;
	}

	static void write(Filepath file, Saved saved) throws IOException
	{
		// the plugin directory isn't created for us
		file.getParent().createDirectories();
		Filepath temp = file.getParent().createTempFile("heatmap", ".tmp");
		try (DataOutputStream out = new DataOutputStream(new BufferedOutputStream(new GZIPOutputStream(temp.openOutputStream()))))
		{
			out.writeInt(MAGIC);
			out.writeInt(VERSION);
			writeSnapshot(out, saved.getHeatmap());
			out.writeInt(saved.getTabHeatmaps().size());
			for (Map.Entry<Integer, Heatmap.Snapshot> tab : saved.getTabHeatmaps().entrySet())
			{
				out.writeInt(tab.getKey());
				writeSnapshot(out, tab.getValue());
			}
			out.close();
			// replace in one step so a crash mid-write can't leave a truncated file
			temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		finally
		{
			temp.deleteIfExists();
		}
	}

	static Saved read(Filepath file) throws IOException
	{
		try (DataInputStream in = new DataInputStream(new BufferedInputStream(new GZIPInputStream(file.openInputStream()))))
		{
			if (in.readInt() != MAGIC || in.readInt() != VERSION)
			{
				throw new IOException("Unrecognised heatmap file");
			}

			Heatmap.Snapshot heatmap = readSnapshot(in);
			int tabCount = in.readInt();
			Map<Integer, Heatmap.Snapshot> tabHeatmaps = new HashMap<>();
			for (int i = 0; i < tabCount; i++)
			{
				tabHeatmaps.put(in.readInt(), readSnapshot(in));
			}
			return new Saved(heatmap, tabHeatmaps);
		}
	}

	private static void writeSnapshot(DataOutputStream out, Heatmap.Snapshot snapshot) throws IOException
	{
		out.writeInt(snapshot.getCellSize());
		out.writeInt(snapshot.getCols());
		out.writeInt(snapshot.getRows());
		for (float h : snapshot.getHeat())
		{
			out.writeFloat(h);
		}
	}

	private static Heatmap.Snapshot readSnapshot(DataInputStream in) throws IOException
	{
		int cellSize = in.readInt();
		int cols = in.readInt();
		int rows = in.readInt();
		if (cellSize <= 0 || cols < 0 || rows < 0 || (long) cols * rows > MAX_CELLS)
		{
			throw new IOException("Corrupt heatmap file");
		}

		float[] heat = new float[cols * rows];
		for (int i = 0; i < heat.length; i++)
		{
			heat[i] = in.readFloat();
		}
		return new Heatmap.Snapshot(cellSize, cols, rows, heat);
	}
}

